const INTERNAL_STYLE_1 = `.playback-controls-play{width:var(--playback-control-button-width, 32px);height:var(--playback-control-button-height, 32px);display:flex;flex:0 0 auto;align-items:stretch;justify-content:stretch;position:relative}.playback-controls-play button{width:100%;height:100%;position:relative;transition:color 0.2s ease-out}.playback-controls-play amp-icon{width:var(--playback-control-icon-width, 32px);height:var(--playback-control-icon-height, 28px);display:block;position:absolute;top:50%;left:50%;transform:translate(-50%, -50%)}button.playback-play__play,button.playback-play__pause,button.playback-play__stop{position:relative;transition:transform 0.2s ease-out;margin:0;padding:0;display:inline-block;border:0;background-color:transparent;outline:none;cursor:pointer;appearance:none;font-family:inherit;font-size:inherit;line-height:inherit;width:100%;height:100%;position:absolute;top:0;left:0;color:var(--playback-controls-play-color, #fff)}button.playback-play__play:enabled:active,button.playback-play__pause:enabled:active,button.playback-play__stop:enabled:active{transform:scale(0.9)}button.playback-play__play:enabled:active::before,button.playback-play__pause:enabled:active::before,button.playback-play__stop:enabled:active::before{width:38px;height:38px;opacity:0.2}button.playback-play__play::before,button.playback-play__pause::before,button.playback-play__stop::before{content:"";width:32px;height:32px;display:block;position:absolute;z-index:-1;top:50%;left:50%;transform:translate(-50%, -50%);border-radius:50%;background:#000;transition:opacity 0.2s ease-out;opacity:0}@media (prefers-color-scheme: dark){button.playback-play__play::before,button.playback-play__pause::before,button.playback-play__stop::before{background:#fff}}button.playback-play__play::-moz-focus-inner,button.playback-play__pause::-moz-focus-inner,button.playback-play__stop::-moz-focus-inner{border:0}button.playback-play__play:hover:not([disabled]),button.playback-play__play:focus-visible:not([disabled]),button.playback-play__pause:hover:not([disabled]),button.playback-play__pause:focus-visible:not([disabled]),button.playback-play__stop:hover:not([disabled]),button.playback-play__stop:focus-visible:not([disabled]){color:var(--playback-controls-play-color-hover, var(--playback-controls-play-color, #fff))}button.playback-play__play:focus-visible,button.playback-play__pause:focus-visible,outline-offset:var(--sk-focus-offset, 1px)}button.playback-play__play[aria-hidden=true],button.playback-play__pause[aria-hidden=true],button.playback-play__stop[aria-hidden=true]{opacity:0;pointer-events:none}button.playback-play__play:disabled,button.playback-play__pause:disabled,button.playback-play__stop:disabled{opacity:0.4;cursor:default}.button__label{position:absolute;clip:rect(1px, 1px, 1px, 1px);clip-path:inset(0 0 99.9% 99.9%);overflow:hidden;height:1px;width:1px;padding:0;border:0}`;
const INTERNAL_STYLE_2 = `.icon{display:block}.icon svg{width:inherit;height:inherit;display:block;color:currentColor;pointer-events:none}.icon svg *{fill:currentColor}`;

type AmpPlaybackControlsProps = {
  theme?: string;
};

const AmpPlaybackControls = memo(function AmpPlaybackControls({
  theme = "dark",
}: AmpPlaybackControlsProps) {
  const containerRef = useRef<HTMLElement>(null);

  // ── 1. Store & Derived state ───────────────────────────────────────
  const {
    currentSong,
    queue,
    playing,
    shuffleEnabled,
    stationMode,
    repeatMode,
    togglePlayback,
    toggleShuffle,
    cycleRepeatMode,
    next,
    previous,
  } = usePlayerStore(
    useShallow((state) => ({
      currentSong: state.currentSong,
      queue: state.queue,
      playing: state.playing,
      shuffleEnabled: state.shuffleEnabled,
      stationMode: state.stationMode,
      repeatMode: state.repeatMode,
      togglePlayback: state.togglePlayback,
      toggleShuffle: state.toggleShuffle,
      cycleRepeatMode: state.cycleRepeatMode,
      next: state.next,
      previous: state.previous,
    })),
  );

  const isPlaying = Boolean(currentSong && playing);
  const playableSongCount = useMemo(
    () => queue.filter((song) => song.playbackUrl).length,
    [queue],
  );

  // ── 2. Slots state cho Portals ─────────────────────────────────────
  const [slots, setSlots] = useState<{
    left: HTMLDivElement | null;
    main: HTMLDivElement | null;
    right: HTMLDivElement | null;
  }>({ left: null, main: null, right: null });

  // ── 3. Khởi tạo Shadow DOM & Slots ────────────────────────────────
  useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const shadow = el.shadowRoot || el.attachShadow({ mode: "open" });

    if (
      "adoptedStyleSheets" in document &&
      shadow.adoptedStyleSheets.length === 0
    ) {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(APPLE_CSS);
      shadow.adoptedStyleSheets = [sheet];
    }

    let controlsDiv = shadow.querySelector(".music-controls");
    if (!controlsDiv) {
      controlsDiv = document.createElement("div");
      controlsDiv.className = "music-controls";

      const leftDiv = document.createElement("div");
      const mainDiv = document.createElement("div");
      mainDiv.className = "music-controls__main";
      const rightDiv = document.createElement("div");

      controlsDiv.appendChild(leftDiv);
      controlsDiv.appendChild(mainDiv);
      controlsDiv.appendChild(rightDiv);

      const style1 = document.createElement("style");
      style1.textContent = INTERNAL_STYLE_1;
      const style2 = document.createElement("style");
      style2.textContent = INTERNAL_STYLE_2;

      shadow.appendChild(controlsDiv);
      shadow.appendChild(style1);
      shadow.appendChild(style2);

      // Lưu tham chiếu DOM để tạo Portal Target
      setSlots({ left: leftDiv, main: mainDiv, right: rightDiv });
    }
  }, []);

  const AppleMusicPlaybackControlsTag =
    "amp-playback-controls" as unknown as React.ComponentType<{
      ref: React.RefObject<HTMLElement | null>;
      class?: string;
      theme?: string;
      hydrated?: string;
      children?: React.ReactNode;
    }>;

  return (
    <AppleMusicPlaybackControlsTag
      ref={containerRef}
      class="[--playback-control-button-width:65px] [--playback-control-icon-width:55px] [--playback-control-icon-height:55px] [--skip-icon-width:50px] [--skip-icon-height:50px] [--shuffle-repeat-button-width:60px] pb-5"
      theme={theme}
      hydrated=""
    >
      {slots.left &&
        createPortal(
          <AmpShuffleButton
            shuffled={shuffleEnabled && !stationMode}
            disabled={playableSongCount < 2 || stationMode}
            onToggle={toggleShuffle}
          />,
          slots.left,
        )}

      {slots.main &&
        createPortal(
          <>
            <AmpSkipButton
              direction="previous"
              onClick={previous}
              disabled={!currentSong}
            />
            <AmpPlayPauseButton
              mode={!isPlaying ? "play" : "pause"}
              onClick={togglePlayback}
              disabled={!currentSong?.playbackUrl}
            />
            <AmpSkipButton
              direction="next"
              onClick={next}
              disabled={!currentSong}
            />
          </>,
          slots.main,
        )}

      {slots.right &&
        createPortal(
          <AmpRepeatButton
            mode={stationMode ? 0 : repeatMode}
            disabled={!currentSong || stationMode}
            onCycle={cycleRepeatMode}
          />,
          slots.right,
        )}
    </AppleMusicPlaybackControlsTag>
  );
});

export default AmpPlaybackControls;
